const nextConversationDisplayID = `-- name: NextConversationDisplayID :one
INSERT INTO organization_counters (organization_id, conversation_seq) VALUES ($1, 1)
ON CONFLICT (organization_id) DO UPDATE SET conversation_seq = organization_counters.conversation_seq + 1
RETURNING conversation_seq
`

// Número de conversación por organización (#1, #2...), sin huecos ni repetidos aunque haya
// altas simultáneas: la fila del contador se bloquea dentro de la transacción del alta.
func (q *Queries) NextConversationDisplayID(ctx context.Context, organizationID uuid.UUID) (int64, error) {
	row := q.db.QueryRow(ctx, nextConversationDisplayID, organizationID)
	var conversation_seq int64
	err := row.Scan(&conversation_seq)
	return conversation_seq, err
}

