const touchConversationInbound = `-- name: TouchConversationInbound :exec
UPDATE conversations
SET last_customer_message_at = GREATEST(last_customer_message_at, $1),
    last_activity_at = GREATEST(last_activity_at, $1),
    last_message_preview = CASE WHEN last_message_preview IS NULL OR $1 >= last_activity_at THEN $2 ELSE last_message_preview END,
    last_message_direction = CASE WHEN last_message_direction IS NULL OR $1 >= last_activity_at THEN 'inbound' ELSE last_message_direction END,
    unread_count = unread_count + 1,
    waiting_since = COALESCE(waiting_since, $1),
    status = CASE WHEN status IN ('pending', 'snoozed') THEN 'open' ELSE status END,
    snoozed_until = CASE WHEN status IN ('pending', 'snoozed') THEN NULL ELSE snoozed_until END,
    updated_at = now()
WHERE id = $3 AND organization_id = $4
`

type TouchConversationInboundParams struct {
	At             pgtype.Timestamptz
	Preview        *string
	ID             uuid.UUID
	OrganizationID uuid.UUID
}

// Un mensaje del cliente: abre la ventana de 24 h, sube los no leídos y reabre lo pendiente o pospuesto.
// Una entrega atrasada (Meta reintenta) nunca hace retroceder la ventana ni la vista previa.
func (q *Queries) TouchConversationInbound(ctx context.Context, arg TouchConversationInboundParams) error {
	_, err := q.db.Exec(ctx, touchConversationInbound,
		arg.At,
		arg.Preview,
		arg.ID,
		arg.OrganizationID,
	)
	return err
}

