const updateConversation = `-- name: UpdateConversation :one
UPDATE conversations
SET status = COALESCE($1::text, status),
    priority = CASE WHEN $2::boolean THEN $3::text ELSE priority END,
    assignee_id = CASE WHEN $4::boolean THEN $5::uuid ELSE assignee_id END,
    handled_by = COALESCE($6::text, handled_by),
    snoozed_until = CASE WHEN $7::boolean THEN $8::timestamptz ELSE snoozed_until END,
    updated_at = now()
WHERE id = $9 AND organization_id = $10
RETURNING id, organization_id, inbox_id, contact_id, display_id, status, priority, assignee_id, handled_by, last_customer_message_at, last_activity_at, last_message_preview, last_message_direction, first_response_at, waiting_since, snoozed_until, unread_count, created_at, updated_at
`

type UpdateConversationParams struct {
	Status         *string
	SetPriority    bool
	Priority       *string
	SetAssignee    bool
	AssigneeID     uuid.NullUUID
	HandledBy      *string
	SetSnoozed     bool
	SnoozedUntil   pgtype.Timestamptz
	ID             uuid.UUID
	OrganizationID uuid.UUID
}

// Cambio parcial de una conversación.
func (q *Queries) UpdateConversation(ctx context.Context, arg UpdateConversationParams) (Conversation, error) {
	row := q.db.QueryRow(ctx, updateConversation,
		arg.Status,
		arg.SetPriority,
		arg.Priority,
		arg.SetAssignee,
		arg.AssigneeID,
		arg.HandledBy,
		arg.SetSnoozed,
		arg.SnoozedUntil,
		arg.ID,
		arg.OrganizationID,
	)
	var i Conversation
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.InboxID,
		&i.ContactID,
		&i.DisplayID,
		&i.Status,
		&i.Priority,
		&i.AssigneeID,
		&i.HandledBy,
		&i.LastCustomerMessageAt,
		&i.LastActivityAt,
		&i.LastMessagePreview,
		&i.LastMessageDirection,
		&i.FirstResponseAt,
		&i.WaitingSince,
		&i.SnoozedUntil,
		&i.UnreadCount,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertWebhookEvent = `-- name: UpsertWebhookEvent :one

INSERT INTO webhook_events (source, event_key, payload) VALUES ($1, $2, $3)
ON CONFLICT (source, event_key) DO UPDATE SET source = webhook_events.source
RETURNING id, processed_at, (xmax = 0) AS inserted
`

type UpsertWebhookEventParams struct {
	Source   string
	EventKey []byte
	Payload  []byte
}

type UpsertWebhookEventRow struct {
	ID          uuid.UUID
	ProcessedAt pgtype.Timestamptz
	Inserted    bool
}

// ---------------------------------------------------------------------------
// Webhooks crudos
// ---------------------------------------------------------------------------
// Registra la entrega o devuelve la ya registrada (misma clave): así se sabe si es nueva o reentrega.
func (q *Queries) UpsertWebhookEvent(ctx context.Context, arg UpsertWebhookEventParams) (UpsertWebhookEventRow, error) {
	row := q.db.QueryRow(ctx, upsertWebhookEvent, arg.Source, arg.EventKey, arg.Payload)
	var i UpsertWebhookEventRow
	err := row.Scan(&i.ID, &i.ProcessedAt, &i.Inserted)
	return i, err
}

const userCanReplyInOrganization = `-- name: UserCanReplyInOrganization :one
SELECT EXISTS (
    SELECT 1 FROM user_organizations uo
    JOIN role_permissions rp ON rp.role_id = uo.role_id AND rp.permission_code = 'org.inbox.reply'
    JOIN users u ON u.id = uo.user_id AND u.is_active
    WHERE uo.user_id = $1 AND uo.organization_id = $2
)
`

type UserCanReplyInOrganizationParams struct {
	UserID         uuid.UUID
	OrganizationID uuid.UUID
}

// ¿Puede este usuario atender conversaciones de la organización? (es miembro y su rol tiene org.inbox.reply,
// o es de la plataforma con acceso a todas). Es lo que se exige a quien se le asigna una conversación.
func (q *Queries) UserCanReplyInOrganization(ctx context.Context, arg UserCanReplyInOrganizationParams) (bool, error) {
	row := q.db.QueryRow(ctx, userCanReplyInOrganization, arg.UserID, arg.OrganizationID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}
